def rod_cutting(arr, n):
    if n <= 0:
        return 0
    dp = [-1] * (n+1)
    return rod_cutting_helper(arr, n, dp)

def rod_cutting_helper(arr, n, dp):
    if n <= 0:
        return 0
    if dp[n] != -1:
        return dp[n]
    max_val = float('-inf') # Initialize max_val as negative infinity
    for i in range(1, n+1): # Iterate from 1 to n instead of 0 to n-1
