#include <vector>
#include <algorithm>
using namespace std;

int countDistinctLCS(string s1, string s2) {
    int m = s1.length();
    int n = s2.length();

    // Create a 2D vector to store the count of LCS of substrings
    vector<vector<int>> dp(m+1, vector<int>(n+1, 0));

    // Fill the dp table
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Get the length of the LCS
    int lcsLength = dp[m][n];

    // Create a 3D vector to store all the LCS
    vector<vector<vector<string>>> lcs(m+1, vector<vector<string>>(n+1, vector<string>()));

    // Fill the lcs table
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1]) {
                for (string lcsString : lcs[i-1][j-1]) {
                    lcs[i][j].push_back(lcsString + s1[i-1]);
                }
            } else {
                if (dp[i-1][j] >= dp[i][j-1]) {
                    lcs[i][j].insert(lcs[i][j].end(), lcs[i-1][j].begin(), lcs[i-1][j].end());
                }
                if (dp[i][j-1] >= dp[i-1][j]) {
                    lcs[i][j].insert(lcs[i][j].end(), lcs[i][j-1].begin(), lcs[i][j-1].end());
                }
            }
        }
    }

    // Get the distinct LCS
    vector<string> distinctLCS;
    for (string lcsString : lcs[m][n]) {
        if (find(distinctLCS.begin(), distinctLCS.end(), lcsString) == distinctLCS.end()) {
            distinctLCS.push_back(lcsString);
        }
    }

    // Print the distinct LCS
    cout << "Distinct LCS: ";
    for (string lcsString : distinctLCS) {
        cout << "\"" << lcsString << "\", ";
    }
    cout << endl;

    return distinctLCS.size();
}

