```c
#include <stdio.h>
#include <string.h>

// Function to find the length of the longest common subsequence
int lcs(char* X, char* Y, int m, int n, int** dp) {
    // Base case: if either of the strings is empty, return 0
    if (m == 0 || n == 0)
        return 0;

    // If the subproblem has already been solved, return the stored value
    if (dp[m][n] != -1)
        return dp[m][n];

    // If the last characters of the strings match
    if (X[m - 1] == Y[n - 1])
        return dp[m][n] = 1 + lcs(X, Y, m - 1, n - 1, dp);
    else
        // If the last characters don't match, find the LCS by excluding one character from either of the strings
        return dp[m][n] = max(lcs(X, Y, m - 1, n, dp), lcs(X, Y, m, n - 1, dp));
}

// Helper function to find the maximum of two integers
int max(int a, int b) {
    return (a > b) ? a : b;
}

// Helper function to create a 2D array
int** createArray(int m, int n) {
    int** arr = (int**)malloc(sizeof(int*) * m);
    for (int i = 0; i < m; i++) {
        arr[i] = (int*)malloc(sizeof(int) * n);
        memset(arr[i], -1, sizeof(int) * n);
    }
    return arr;
}

// Helper function to free the dynamically allocated memory
void freeArray(int** arr, int m) {
    for (int i = 0; i < m; i++)
        free(arr[i]);
    free(arr);
}

int main() {
    char X[] = "AGGTAB";
    char Y[] = "GXTXAYB";

    int m = strlen(X);
    int n = strlen(Y);

    // Create a 2D array to store the solutions to subproblems
    int** dp = createArray(m + 1, n + 1);

    // Find the length of the longest common subsequence
    int length = lcs(X, Y, m, n, dp);

    printf("Length of LCS: %d\n", length);

    // Free the dynamically allocated memory
    freeArray(dp, m + 1);

    return 0;
}
```

In this implementation, we use memoization to store the solutions to subproblems in a 2D array `dp`. The function `lcs` recursively computes the length of the longest common subsequence by considering different cases. The helper functions `max`, `createArray`, and `freeArray` are used to find the maximum of two integers, create a 2D array, and free the dynamically allocated memory, respectively.

The time complexity of this solution is O(n^2) because we solve each subproblem only once and store its solution for future use.

