```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class LongestIncreasingSubsequence {
    public static List<Integer> findLongestIncreasingSubsequence(List<Integer> input) {
        int n = input.size();
        int[] dp = new int[n];
        int[] prev = new int[n];

        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            prev[i] = -1;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (input.get(i) > input.get(j)) {
                    if (dp[j] + 1 > dp[i]) {
                        dp[i] = dp[j] + 1;
                        prev[i] = j;
                    }
                }
            }
        }

        int maxLength = 0;
        for (int i = 0; i < n; i++) {
            maxLength = Math.max(maxLength, dp[i]);
        }

        List<Integer> subsequence = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (dp[i] == maxLength) {
                int index = i;
                while (index != -1) {
                    subsequence.add(input.get(index));
                    index = prev[index];
                }
            }
        }

        Collections.reverse(subsequence);
        return subsequence;
    }

    public static void main(String[] args) {
        List<Integer> input = new ArrayList<>();
        input.add(8);
        input.add(10);
        input.add(1);
        input.add(4);
        input.add(15);
        input.add(6);
        input.add(7);

        List<Integer> longestIncreasingSubsequence = findLongestIncreasingSubsequence(input);
        System.out.println(longestIncreasingSubsequence);
    }
}
