        int startIndex1 = str1.indexOf(longestCommonSubstring);
        int endIndex1 = startIndex1 + longestCommonSubstring.length() - 1;
        System.out.println("Starting Index in String 1: " + startIndex1);
        System.out.println("Ending Index in String 1: " + endIndex1);

        int startIndex2 = str2.indexOf(longestCommonSubstring);
        int endIndex2 = startIndex2 + longestCommonSubstring.length() - 1;
        System.out.println("Starting Index in String 2: " + startIndex2);
        System.out.println("Ending Index in String 2: " + endIndex2);
    }

    private static String findLongestCommonSubstring(String str1, String str2) {
        int[][] dp = new int[str1.length() + 1][str2.length() + 1];
        int maxLength = 0;
        int endIndex = -1;

        for (int i = 1; i <= str1.length(); i++) {
            for (int j = 1; j <= str2.length(); j++) {
                if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                    if (dp[i][j] > maxLength) {
                        maxLength = dp[i][j];
                        endIndex = i - 1;
                    }
                }
            }
        }

        if (maxLength == 0) {
            return "";
        } else {
            return str1.substring(endIndex - maxLength + 1, endIndex + 1);
        }
    }
}
